function range(n){var a=[];for(var i=0;i<n;i++)a.push(i);return a;}
function shuffle(a,rng){a=a.slice();for(var i=a.length-1;i>0;i--){var j=Math.floor(rng()*(i+1));var t=a[i];a[i]=a[j];a[j]=t;}return a;}
function pick(rng,n){var idx=shuffle(range(WORDS.length),rng).slice(0,Math.min(n,WORDS.length));return idx.map(function(i){return WORDS[i];});}
function score(ans, words){var c=0;for(var i=0;i<words.length;i++){if((ans[i]||'').trim().toLowerCase()===words[i].w.toLowerCase())c++;}return {correct:c,total:words.length};}
